package com.tamzode.tracker;

import java.sql.Date;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

@RestController @RequestMapping("/api")
public class TrackerController {
 private final JdbcTemplate db;
 public TrackerController(JdbcTemplate db){this.db=db;}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","ok");}
 private static final String PROJECT_SELECT="SELECT p.id,p.name,p.description,p.category,p.technology,p.status,p.priority,p.start_date AS \"startDate\",p.deadline,p.owner,p.notes,p.useful_links AS \"usefulLinks\",p.repository_url AS \"repositoryUrl\",p.progress_mode AS \"progressMode\",p.created_at AS \"createdAt\",p.updated_at AS \"updatedAt\",count(t.id)::int AS \"taskCount\",(SELECT count(*)::int FROM milestones m WHERE m.project_id=p.id) AS \"milestoneCount\",count(t.id) FILTER(WHERE t.status='Done')::int AS \"completedTasks\",CASE WHEN count(t.id)=0 THEN 0 ELSE round(100.0*count(t.id) FILTER(WHERE t.status='Done')/count(t.id))::int END AS progress FROM projects p LEFT JOIN tasks t ON t.project_id=p.id";
 @GetMapping("/dashboard") Map<String,Object> dashboard(){return db.queryForMap("SELECT (SELECT count(*) FROM projects)::int AS total,(SELECT count(*) FROM projects WHERE status='In Progress')::int AS active,(SELECT count(*) FROM tasks WHERE status='Done')::int AS completed,(SELECT count(*) FROM tasks WHERE status<>'Done')::int AS pending,(SELECT count(*) FROM tasks WHERE status<>'Done' AND due_date>=CURRENT_DATE AND due_date<CURRENT_DATE+7)::int AS upcoming,(SELECT count(*) FROM tasks WHERE status<>'Done' AND due_date<CURRENT_DATE)::int AS overdue");}
 private List<Map<String,Object>> projects(String where,Object...args){return db.queryForList(PROJECT_SELECT+" "+where+" GROUP BY p.id ORDER BY p.created_at DESC",args);}
 @GetMapping("/projects") List<Map<String,Object>> getProjects(@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="100") int limit){var args=new java.util.ArrayList<Object>();String where="";if(status!=null){where="WHERE p.status=?";args.add(status);}return db.queryForList(PROJECT_SELECT+" "+where+" GROUP BY p.id ORDER BY p.created_at DESC LIMIT ? OFFSET ?",append(args,Math.max(1,Math.min(limit,200)),Math.max(0,offset)).toArray());}
 @GetMapping("/projects/{id}") Map<String,Object> getProject(@PathVariable long id){return project(id);}
 private Map<String,Object> project(long id){return projects("WHERE p.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found"));}
 record ProjectInput(@NotBlank @Size(max=140) String name,String description,@Size(max=100) String category,@Size(max=300) String technology,String status,String priority,java.time.LocalDate startDate,java.time.LocalDate deadline,@Size(max=120) String owner,String notes,String usefulLinks,String repositoryUrl,String progressMode){}
 @PostMapping("/projects") @Transactional Map<String,Object> createProject(@Valid @RequestBody ProjectInput p){db.update("INSERT INTO projects(name,description,category,technology,status,priority,start_date,deadline,owner,notes,useful_links,repository_url,progress_mode) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",p.name(),p.description(),p.category(),p.technology(),value(p.status(),"Planned",Set.of("Planned","In Progress","On Hold","Completed")),value(p.priority(),"Medium",Set.of("Low","Medium","High","Urgent")),p.startDate(),p.deadline(),p.owner(),p.notes(),p.usefulLinks(),p.repositoryUrl(),value(p.progressMode(),"tasks",Set.of("tasks","milestones")));long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('projects','id'))",Long.class);log("created","project",id,p.name(),"Project created");return project(id);}
 @PutMapping("/projects/{id}") @Transactional Map<String,Object> updateProject(@PathVariable long id,@Valid @RequestBody ProjectInput p){project(id);db.update("UPDATE projects SET name=?,description=?,category=?,technology=?,status=?,priority=?,start_date=?,deadline=?,owner=?,notes=?,useful_links=?,repository_url=?,progress_mode=?,updated_at=now() WHERE id=?",p.name(),p.description(),p.category(),p.technology(),value(p.status(),"Planned",Set.of("Planned","In Progress","On Hold","Completed")),value(p.priority(),"Medium",Set.of("Low","Medium","High","Urgent")),p.startDate(),p.deadline(),p.owner(),p.notes(),p.usefulLinks(),p.repositoryUrl(),value(p.progressMode(),"tasks",Set.of("tasks","milestones")),id);log("updated","project",id,p.name(),"Project details updated");return project(id);}
 @DeleteMapping("/projects/{id}") @Transactional Map<String,String> deleteProject(@PathVariable long id){Map<String,Object> p=project(id);db.update("DELETE FROM projects WHERE id=?",id);log("deleted","project",id,(String)p.get("name"),"Project and related records deleted");return Map.of("message","Project deleted");}

 private static final String TASK_SELECT="SELECT t.id,t.title,t.description,t.project_id AS \"projectId\",p.name AS \"projectName\",t.status,t.priority,t.due_date AS \"dueDate\",t.assignee,t.tags,t.notes,t.created_at AS \"createdAt\",t.updated_at AS \"updatedAt\" FROM tasks t JOIN projects p ON p.id=t.project_id";
 @GetMapping("/tasks") List<Map<String,Object>> getTasks(@RequestParam(required=false) Long projectId,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="200") int limit){StringBuilder q=new StringBuilder(TASK_SELECT);var args=new java.util.ArrayList<Object>();if(projectId!=null){q.append(" WHERE t.project_id=?");args.add(projectId);}if(status!=null){q.append(args.isEmpty()?" WHERE":" AND").append(" t.status=?");args.add(status);}q.append(" ORDER BY t.due_date NULLS LAST,t.created_at DESC LIMIT ? OFFSET ?");args.add(Math.max(1,Math.min(limit,500)));args.add(Math.max(0,offset));return db.queryForList(q.toString(),args.toArray());}
 record TaskInput(@NotBlank @Size(max=180) String title,String description,@NotNull Long projectId,String status,String priority,java.time.LocalDate dueDate,@Size(max=120) String assignee,List<String> tags,String notes){}
 @PostMapping("/tasks") @Transactional Map<String,Object> createTask(@Valid @RequestBody TaskInput t){ensureProject(t.projectId());db.update("INSERT INTO tasks(title,description,project_id,status,priority,due_date,assignee,tags,notes) VALUES(?,?,?,?,?,?,?,?,?)",t.title(),t.description(),t.projectId(),value(t.status(),"To Do",Set.of("To Do","In Progress","In Review","Done")),value(t.priority(),"Medium",Set.of("Low","Medium","High","Urgent")),t.dueDate(),t.assignee(),t.tags()==null?new String[]{}:t.tags().toArray(String[]::new),t.notes());long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('tasks','id'))",Long.class);log("created","task",id,t.title(),"Task created");return task(id);}
 @PutMapping("/tasks/{id}") @Transactional Map<String,Object> updateTask(@PathVariable long id,@Valid @RequestBody TaskInput t){task(id);ensureProject(t.projectId());db.update("UPDATE tasks SET title=?,description=?,project_id=?,status=?,priority=?,due_date=?,assignee=?,tags=?,notes=?,updated_at=now() WHERE id=?",t.title(),t.description(),t.projectId(),value(t.status(),"To Do",Set.of("To Do","In Progress","In Review","Done")),value(t.priority(),"Medium",Set.of("Low","Medium","High","Urgent")),t.dueDate(),t.assignee(),t.tags()==null?new String[]{}:t.tags().toArray(String[]::new),t.notes(),id);log("updated","task",id,t.title(),"Task updated");return task(id);}
 @PatchMapping("/tasks/{id}/status") @Transactional Map<String,Object> taskStatus(@PathVariable long id,@RequestBody Map<String,String> body){Map<String,Object> before=task(id);String s=value(body.get("status"),null,Set.of("To Do","In Progress","In Review","Done"));db.update("UPDATE tasks SET status=?,updated_at=now() WHERE id=?",s,id);if(!s.equals(before.get("status")))log(s.equals("Done")?"completed":"status changed","task",id,(String)before.get("title"),"Status: "+before.get("status")+" → "+s);return task(id);}
 @DeleteMapping("/tasks/{id}") Map<String,String> deleteTask(@PathVariable long id){Map<String,Object> t=task(id);db.update("DELETE FROM tasks WHERE id=?",id);log("deleted","task",id,(String)t.get("title"),"Task deleted");return Map.of("message","Task deleted");}
 private Map<String,Object> task(long id){return db.queryForList(TASK_SELECT+" WHERE t.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found"));}
 private void ensureProject(long id){if(db.queryForObject("SELECT count(*) FROM projects WHERE id=?",Integer.class,id)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an existing project");}

 @GetMapping("/milestones") List<Map<String,Object>> milestones(@RequestParam(required=false) Long projectId){return projectId==null?db.queryForList("SELECT m.id,m.name,m.description,m.project_id AS \"projectId\",p.name AS \"projectName\",m.target_date AS \"targetDate\",m.status,m.created_at AS \"createdAt\" FROM milestones m JOIN projects p ON p.id=m.project_id ORDER BY m.target_date NULLS LAST"):db.queryForList("SELECT m.id,m.name,m.description,m.project_id AS \"projectId\",p.name AS \"projectName\",m.target_date AS \"targetDate\",m.status,m.created_at AS \"createdAt\" FROM milestones m JOIN projects p ON p.id=m.project_id WHERE m.project_id=? ORDER BY m.target_date NULLS LAST",projectId);}
 record MilestoneInput(@NotBlank @Size(max=160) String name,String description,@NotNull Long projectId,java.time.LocalDate targetDate,String status){}
 @PostMapping("/milestones") @Transactional Map<String,Object> addMilestone(@Valid @RequestBody MilestoneInput m){ensureProject(m.projectId());db.update("INSERT INTO milestones(name,description,project_id,target_date,status) VALUES(?,?,?,?,?)",m.name(),m.description(),m.projectId(),m.targetDate(),value(m.status(),"Planned",Set.of("Planned","In Progress","Completed")));long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('milestones','id'))",Long.class);log("created","milestone",id,m.name(),"Milestone created");return db.queryForMap("SELECT id,name,description,project_id AS \"projectId\",target_date AS \"targetDate\",status FROM milestones WHERE id=?",id);}
 @PutMapping("/milestones/{id}") @Transactional Map<String,Object> updateMilestone(@PathVariable long id,@Valid @RequestBody MilestoneInput m){if(db.update("UPDATE milestones SET name=?,description=?,project_id=?,target_date=?,status=?,updated_at=now() WHERE id=?",m.name(),m.description(),m.projectId(),m.targetDate(),value(m.status(),"Planned",Set.of("Planned","In Progress","Completed")),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Milestone not found");log("updated","milestone",id,m.name(),"Milestone updated");return db.queryForMap("SELECT id,name,description,project_id AS \"projectId\",target_date AS \"targetDate\",status FROM milestones WHERE id=?",id);}
 @DeleteMapping("/milestones/{id}") Map<String,String> deleteMilestone(@PathVariable long id){if(db.update("DELETE FROM milestones WHERE id=?",id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Milestone not found");return Map.of("message","Milestone deleted");}

 record UpdateInput(@NotBlank String workedOn,String completed,String blockers,String nextSteps){}
 @PostMapping("/daily-updates") @Transactional Map<String,Object> addDailyUpdate(@Valid @RequestBody UpdateInput u){db.update("INSERT INTO daily_updates(worked_on,completed,blockers,next_steps) VALUES(?,?,?,?)",u.workedOn(),u.completed(),u.blockers(),u.nextSteps());long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('daily_updates','id'))",Long.class);log("logged","daily update",id,"Daily progress note",u.workedOn());return db.queryForMap("SELECT id,worked_on AS \"workedOn\",completed,blockers, next_steps AS \"nextSteps\",created_at AS \"createdAt\" FROM daily_updates WHERE id=?",id);}
 @GetMapping("/daily-updates") List<Map<String,Object>> updates(@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){return db.queryForList("SELECT id,worked_on AS \"workedOn\",completed,blockers,next_steps AS \"nextSteps\",created_at AS \"createdAt\" FROM daily_updates ORDER BY created_at DESC LIMIT ? OFFSET ?",Math.max(1,Math.min(limit,200)),Math.max(0,offset));}
 @GetMapping("/activity") List<Map<String,Object>> activity(@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){return db.queryForList("SELECT id,action,entity_type AS \"entityType\",entity_name AS \"entityName\",details,created_at AS \"createdAt\" FROM activity ORDER BY created_at DESC LIMIT ? OFFSET ?",Math.max(1,Math.min(limit,200)),Math.max(0,offset));}
 private void log(String action,String type,long id,String name,String details){db.update("INSERT INTO activity(action,entity_type,entity_id,entity_name,details) VALUES(?,?,?,?,?)",action,type,id,name,details);}
 private static String value(String s,String d,Set<String> allowed){String v=s==null||s.isBlank()?d:s;if(v==null||!allowed.contains(v))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid value: "+v);return v;}
 private static java.util.List<Object> append(java.util.List<Object> a,Object...v){a.addAll(java.util.Arrays.asList(v));return a;}
}
